#!/usr/bin/env node
/**
 * The basket, on the website and in the app: does each part fit the buyer's car (the default car of My Garage)?
 *   Fits      a green ribbon across the corner of the photo: "✓ FIT" / «✓ متوافقة», and "✓ Compatible with your <car>" under the name.
 *   Not fit   a red ribbon: "✕ NOT FIT" / «✕ غير متوافقة», "For <the part's car> — your car is <your car>", and "Find it for my car".
 * In Arabic the ribbon is in the other corner. No car in My Garage, or a part that fits any car: no ribbon.
 * Needs patch-cart-select first (and in the app, patch-gold-ticks may be applied or not).
 *
 *   node scripts/patch-fit-ribbon.js            dry run: says what it would change, writes nothing
 *   node scripts/patch-fit-ribbon.js --write    applies it (each changed file is saved as <file>.before-fit-ribbon first)
 *
 * A file that is not exactly what the patch expects is NOT changed (the whole patch stops, so nothing is half applied).
 * Windows (CRLF) line endings are handled. Running it twice is harmless ("already").
 */
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const write = process.argv.includes('--write');
