  if (!e.froms.includes(flat)) { console.log(`REFUSED   ${e.file}: its text is not what this patch expects, so nothing was changed. Send this file.`); problems++; continue; }
  const after = s.includes('\r\n') ? e.to.replace(/\n/g, '\r\n') : e.to;
